#ifndef PILA_H
#define PILA_H

#define MAX 8

typedef enum {
  FALSO,
  VERDADERO
} TBool;

typedef struct {
  int datos[MAX];
  int tope;
} TPila;

void inicializar(TPila *p);
void apilar(TPila *p, int x);
int desapilar(TPila *p);
int cima(TPila p);
TBool vacia(TPila p);
TBool llena(TPila p);

#endif

