#include "pila.h"

void inicializar(TPila *p) {
  p->tope = 0;
}

void apilar(TPila *p, int x) {
  p->datos[p->tope] = x;
  p->tope = p->tope + 1;
}

int desapilar(TPila *p) {
  p->tope = p->tope - 1;
  return p->datos[p->tope];
}

int cima(TPila p) {
  return p.datos[p.tope - 1];
}

TBool vacia(TPila p) {
  if (p.tope == 0) {
    return VERDADERO;
  }
  return FALSO;
}

TBool llena(TPila p) {
  if (p.tope == MAX) {
    return VERDADERO;
  }
  return FALSO;
}
